import{_ as o,a0 as m,w as r,s,ao as l,I as a,x as e,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux Uptime 命令，讓你知道你的系統運行了多久 | LCTT x X-CMD","titleTemplate":false,"description":"Linux Uptime 命令，讓你知道你的系統運行了多久 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Uptime 命令，讓你知道你的系統運行了多久 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Uptime 命令，讓你知道你的系統運行了多久 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Linux Uptime Command – Find How Long Your System Been Running","title":"Linux Uptime 命令，讓你知道你的系統運行了多久","tag":"201312","desc":""},"relativePath":"201312/Linux Uptime Command – Find How Long Your System Been Running.md","filePath":"[post].md"}'),u={name:"201312/Linux Uptime Command – Find How Long Your System Been Running.md"};function d(x,t,g,h,L,T){const n=m("Link");return r(),s("div",null,[t[11]||(t[11]=l(`<h1 id="linux-uptime-命令-讓你知道你的系統運行了多久" tabindex="-1">Linux Uptime 命令，讓你知道你的系統運行了多久 <a class="header-anchor" href="#linux-uptime-命令-讓你知道你的系統運行了多久" aria-label="Permalink to “Linux Uptime 命令，讓你知道你的系統運行了多久”">​</a></h1><p><img src="http://linoxide.com/wp-content/uploads/2013/11/linux-uptime-command.png" alt=""></p><p>對於一些人來説系統運行了多久是無關緊要的，但是對於服務器管理員來説，這是相當重要的信息。服務器在運行重要應用的時候，必須儘量保證長時間的穩定運行，有時候甚至要求零宕機。那麼我們怎麼才能知道服務器運行了多久呢？</p><p>在Linux 下，我們可以使用uptime 命令，而且此命令不必使用root 權限。uptime 命令在系統中已經默認安裝了。</p><p>語法如下：</p><pre><code>$ uptime
</code></pre><p>你會在屏幕上看到如下顯示：</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime.png" alt=""></p><p>這些信息保存在/proc/uptime 文件中，雖然是以文本方式保存，但是這些數據卻不能直接顯示，這就需要我們使用uptime 命令來翻譯它。</p><p>以下是如何解讀uptime 提供的信息：</p><h3 id="系統時間" tabindex="-1">系統時間 <a class="header-anchor" href="#系統時間" aria-label="Permalink to “系統時間”">​</a></h3><p>在圖1中，左起第一條信息是14:04:39，這就是當前系統時間，以24小時格式輸出。</p><h3 id="系統運行時間" tabindex="-1">系統運行時間 <a class="header-anchor" href="#系統運行時間" aria-label="Permalink to “系統運行時間”">​</a></h3><p>第二條信息<strong>Up 1004 days, 12:20</strong>，這是顯示你的系統運行時間。圖1 顯示你的系統已經運行了1004天12小時20分鐘，如果你的系統沒有運行超過24小時，這裏將只會顯示小時分鐘或者只顯示分鐘。注意圖2、圖3的信息，當系統重啓後將會清零。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime_minutes.png" alt=""></p><p><img src="http://linoxide.com/wp-content/uploads/2013/11/uptime_hours1.png" alt=""></p><h3 id="已登錄用户的數量" tabindex="-1">已登錄用户的數量 <a class="header-anchor" href="#已登錄用户的數量" aria-label="Permalink to “已登錄用户的數量”">​</a></h3><p>第三部分的信息是顯示已登陸用户的數量。在圖1中，顯示的是<strong>1 user</strong> ，即當前登錄用户數量。當多個用户在同時登陸系統時，uptime 命令將告訴你用户的數量。</p><h3 id="平均負載量" tabindex="-1">平均負載量 <a class="header-anchor" href="#平均負載量" aria-label="Permalink to “平均負載量”">​</a></h3><p>最後一個信息是系統的平均負載量。回到圖1，你看到這樣帶兩位小數的數字<strong>0.25, 0.25, 0.19</strong>可以換算成百分比，即0.25和0.19分別代表着25%和19%。0.25, 0.25, 0.19分別代表着過去1分鐘、5分鐘、15分鐘系統的平均負載量。負載量越低意味着你的系統性能越好。</p><p>這就是<strong>uptime</strong> 命令的日常使用指導，如果想獲取更詳細的信息，請通過輸入<strong>man uptime</strong> 進入uptime 命令的manual 頁面來查看。</p><p>你的機器已經運行多久了？貼出你的uptime給大家看看吧。</p><hr>`,23)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(n,{href:"http://linoxide.com/linux-command/linux-uptime-command/"},{default:p(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-uptime-command/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),i(n,{href:"https://github.com/NearTan"},{default:p(()=>[...t[2]||(t[2]=[e("NearTan",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),i(n,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:p(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const c=o(u,[["render",d]]);export{_ as __pageData,c as default};
